/**
 * Extracts ABIs from Foundry build output (contracts/out) into src/abi/*.ts as `as const` arrays.
 * Run `forge build` in contracts/ first, then `pnpm --filter @session-firewall/sdk abi`.
 * The generated files are committed so the SDK builds without Foundry.
 */
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, "../../../contracts/out");
const dest = join(here, "../src/abi");

/** [solidity file, contract name, exported const name] */
const CONTRACTS: [string, string, string][] = [
  ["ISmartSessions.sol", "ISmartSessions", "firewallSmartSessionsAbi"],
  [
    "FirewallOwnerValidator.sol",
    "FirewallOwnerValidator",
    "firewallOwnerValidatorAbi",
  ],
  ["FirewallModule.sol", "FirewallModule", "firewallModuleAbi"],
  ["FirewallHook.sol", "FirewallHook", "firewallHookAbi"],
  [
    "FirewallActionPolicy.sol",
    "FirewallActionPolicy",
    "firewallActionPolicyAbi",
  ],
  ["NoSignaturePolicy.sol", "NoSignaturePolicy", "noSignaturePolicyAbi"],
  ["FirewallErrors.sol", "FirewallErrors", "firewallErrorsAbi"],
  [
    "ReferenceMarketAdapter.sol",
    "ReferenceMarketAdapter",
    "referenceMarketAdapterAbi",
  ],
  ["ReferenceMarket.sol", "ReferenceMarket", "referenceMarketAbi"],
  ["ReferenceMarket.sol", "OutcomeShares", "outcomeSharesAbi"],
  ["MockUSDC.sol", "MockUSDC", "mockUsdcAbi"],
];

const files: string[] = [];
const exports: string[] = [];
for (const [sol, name, constName] of CONTRACTS) {
  const artifact = JSON.parse(
    readFileSync(join(out, sol, `${name}.json`), "utf8"),
  );
  const file = `${name.charAt(0).toLowerCase()}${name.slice(1)}.ts`;
  const body = `// Generated by scripts/extract-abis.ts from contracts/out/${sol}/${name}.json. Do not edit.\nexport const ${constName} = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;
  writeFileSync(join(dest, file), body);
  files.push(join(dest, file));
  exports.push(
    `export { ${constName} } from "./${file.replace(/\.ts$/, ".js")}";`,
  );
}

// ExecutionDecoder is an internal library: its only ABI item is `error Malformed()`.
const malformed = `// Generated by scripts/extract-abis.ts (ExecutionDecoder library). Do not edit.\nexport const executionDecoderAbi = [{ type: "error", name: "Malformed", inputs: [] }] as const;\n`;
writeFileSync(join(dest, "executionDecoder.ts"), malformed);
files.push(join(dest, "executionDecoder.ts"));
exports.push(`export { executionDecoderAbi } from "./executionDecoder.js";`);

const index = join(dest, "index.ts");
writeFileSync(
  index,
  `// Generated by scripts/extract-abis.ts. Do not edit.\n${exports.join("\n")}\nexport * from "./external.js";\n`,
);
files.push(index);

execFileSync("pnpm", ["exec", "biome", "format", "--write", ...files], {
  stdio: "inherit",
});
console.log(`wrote ${files.length} files to ${dest}`);
